async function invitationShareClick(button){
 const url=button.dataset.shareUrl,title=button.dataset.shareTitle;
 const status=button.closest('footer').querySelector('.ow-invite-share-status');
 if(!url){status.textContent='편집 화면에서 저장하고 공유 링크를 만들어 주세요.';return;}
 if(button.dataset.shareKind==='kakao'){
  if(window.Kakao&&window.Kakao.isInitialized&&window.Kakao.isInitialized()&&window.Kakao.Share){
   try{window.Kakao.Share.sendDefault({objectType:'text',text:title,link:{mobileWebUrl:url,webUrl:url}});return;}catch(e){}
  }
  if(navigator.share){
   try{await navigator.share({title,url});status.textContent='공유창을 닫았어요.';return;}catch(e){if(e.name==='AbortError')return;}
  }
 }
 try{
  await navigator.clipboard.writeText(url);
  status.textContent=button.dataset.shareKind==='kakao'?'링크를 복사했어요. 카카오톡 대화방에 붙여넣어 주세요.':'청첩장 링크를 복사했어요.';
 }catch(e){
  status.textContent='아래 링크를 길게 눌러 복사해 주세요.';
  let field=button.closest('footer').querySelector('textarea');
  if(!field){field=document.createElement('textarea');field.readOnly=true;field.setAttribute('aria-label','복사할 청첩장 링크');field.style.cssText='width:100%;box-sizing:border-box;margin-top:12px;padding:12px;font:12px sans-serif;';status.after(field);}
  field.value=url;field.focus();field.select();
 }
}

function markup(d,animate){return untypedMarkup(d,animate).replace('<article ','<article data-dearly-type="'+cleanTypeface(d.typeface)+'" ');}
function untypedMarkup(d,animate){
 const palette=coverPalettes[d.theme]||coverPalettes[0];const tone='--paper:'+palette.paper+';--ink:'+palette.ink+';--line:'+palette.line+';--ow-ink:'+palette.ink+';background:'+palette.paper+';color:'+palette.ink;const old=baseMarkup(d,animate).replace('<div class="ow-invite-body">','<div class="ow-invite-body" style="'+tone+'">');if(d.content===-1)return old;
 const c=[0,1,2].includes(d.content)?d.content:0;
 const ornament='<svg class="oc-ornament" viewBox="0 0 48 28" fill="none" stroke="currentColor" stroke-width="1" aria-hidden="true"><path d="M6 24 40 5M14 19Q5 8 20 15M25 13Q17 2 30 10M21 16Q34 23 33 9"/></svg>';
 const names='<h3 class="oc-names">'+esc(d.name1)+' &amp; '+esc(d.name2)+'</h3>';
 const letter='<div class="oc-letter"><p class="oc-kicker">소중한 당신을 초대합니다</p>'+ornament+names+'<p class="oc-message">'+esc(d.message)+'</p><p class="oc-date">'+esc(formatted(d))+'<br>'+esc(d.time)+'</p></div>';
 const gallery=d.contentPhotos&&!d.personal?.photo?'<figure class="oc-gallery"><img src="'+contentAssets[c===1?38:16]+'" alt="웨딩 사진 모음 예시" loading="lazy"></figure>':'';
 const story=d.contentPhotos&&!d.personal?.photo&&c===2?'<figure class="oc-story"><img src="'+contentAssets[11]+'" alt="노을 앞에 선 두 사람의 예시 사진" loading="lazy"></figure>':'';
 const portrait=d.contentPhotos&&!d.personal?.photo&&c===0?'<figure class="oc-story"><img src="'+contentAssets[7]+'" alt="아치형 웨딩 사진 예시" loading="lazy"></figure>':'';
 const location='<div class="oc-location"><p class="oc-kicker">함께할 그날</p><h4>오시는 길</h4><strong>'+esc(d.venue)+'</strong><p>'+esc(d.address||'자세한 장소 안내는 추후 전해드리겠습니다.')+'</p><p>'+esc(formatted(d))+' · '+esc(d.time)+'</p>'+mapLink(d)+'<button type="button" class="ow-calendar">달력에 일정 담기</button></div>';
 const body='<div class="ow-content" style="'+tone+'" data-content="'+c+'">'+letter+portrait+story+gallery+invitationExtras(d,location)+'<p class="oc-end">함께해 주셔서 감사합니다.</p></div>';
 return old.slice(0,old.indexOf('<div class="ow-invite-body"'))+body+'</article>';
}
function syncContent(){root.querySelectorAll('[data-content-choice]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.contentChoice)===contentStyle)));}
function scrollContent(top){const a=root.querySelector('#ow-live article');if(!a)return;const body=a.querySelector('.ow-content,.ow-invite-body');a.scrollTo({top:top?0:(body?body.offsetTop-a.offsetTop:0),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}

function render(){syncContent();syncTypography();document.getElementById('ow-live').innerHTML=markup(data(),false);root.querySelectorAll('[data-theme].ow-theme').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.theme)===theme)));document.getElementById('ow-share-box').hidden=true;}
function populate(d){typeface=cleanTypeface(d.typeface);personal=cleanPersonal(d.personal);contentStyle=d.content;document.getElementById('oc-photos').checked=d.contentPhotos;theme=d.theme;fields.forEach(k=>form.querySelector('[name="'+k+'"]').value=d[k]);form.querySelector('[name="motion"]').checked=d.motion;render();}
try{const saved=localStorage.getItem('orae-wedding-v1');if(saved){populate(normalized(JSON.parse(saved)));status.textContent='이 브라우저에 저장한 내용을 불러왔어요.';}else render();}catch(e){render();}
