function encode(d){let b='';new TextEncoder().encode(JSON.stringify(d)).forEach(v=>b+=String.fromCharCode(v));return btoa(b).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');}
function decode(s){let t=s.replaceAll('-','+').replaceAll('_','/');while(t.length%4)t+='=';return normalized(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(t),c=>c.charCodeAt(0)))));}
